import UIKit
import Flutter
import BackgroundTasks
import UserNotifications

@main
@objc class AppDelegate: FlutterAppDelegate {
  override func application(_ application: UIApplication,
      didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
    GeneratedPluginRegistrant.register(with: self)
    // Must be registered before launch finishes.
    BGTaskScheduler.shared.register(forTaskWithIdentifier: "com.crier.app.publish.refresh", using: nil) { task in
      self.handlePublishRefresh(task: task as! BGAppRefreshTask)
    }
    UNUserNotificationCenter.current().delegate = self  // required by flutter_local_notifications
    return super.application(application, didFinishLaunchingWithOptions: launchOptions)
  }

  func schedulePublishRefresh(at date: Date) {
    let req = BGAppRefreshTaskRequest(identifier: "com.crier.app.publish.refresh")
    req.earliestBeginDate = date  // floor only; system decides actual time
    try? BGTaskScheduler.shared.submit(req)
  }

  func handlePublishRefresh(task: BGAppRefreshTask) {
    task.expirationHandler = { /* cancel in-flight work */ }
    // call into Dart via MethodChannel / workmanager callback, then:
    task.setTaskCompleted(success: true)
  }
}

import 'package:android_alarm_manager_plus/android_alarm_manager_plus.dart';
import 'package:permission_handler/permission_handler.dart';

@pragma('vm:entry-point')
Future<void> publishAlarmCallback(int id) async {
  // Runs in a separate isolate: re-open DB, load post `id`, start FGS, publish, reschedule retries via workmanager.
}

Future<bool> armExact(int postId, DateTime dueAt) async {
  await AndroidAlarmManager.initialize();
  var status = await Permission.scheduleExactAlarm.status;
  if (!status.isGranted) status = await Permission.scheduleExactAlarm.request(); // opens 'Alarms & reminders'
  final exact = status.isGranted;
  return AndroidAlarmManager.oneShotAt(
    dueAt, postId, publishAlarmCallback,
    exact: exact,          // falls back to inexact (setWindow) if denied
    wakeup: true,
    allowWhileIdle: true,  // setExactAndAllowWhileIdle: fires in Doze, max 1 per 9 min per app
    alarmClock: false,     // true = setAlarmClock (shows alarm icon, exits Doze early) - heavier, reserve for opt-in
    rescheduleOnReboot: true,
  );
}

import 'package:flutter_local_notifications/flutter_local_notifications.dart';
import 'package:timezone/timezone.dart' as tz;

Future<void> armReminder(FlutterLocalNotificationsPlugin fln, int postId, DateTime dueAtUtc, String title) async {
  await fln.zonedSchedule(
    postId,
    'Time to publish',
    'Tap to post "$title"',
    tz.TZDateTime.from(dueAtUtc, tz.local),
    const NotificationDetails(
      android: AndroidNotificationDetails('publish', 'Scheduled posts', importance: Importance.max, priority: Priority.high),
      iOS: DarwinNotificationDetails(interruptionLevel: InterruptionLevel.timeSensitive),
      macOS: DarwinNotificationDetails(),
      windows: WindowsNotificationDetails(),
    ),
    androidScheduleMode: AndroidScheduleMode.exactAllowWhileIdle, // or .inexact when exact permission denied
    payload: 'publish:$postId',
  );
  // Dart runs ONLY when the user taps: handle in onDidReceiveNotificationResponse -> publish(postId)
}

import Cocoa
import FlutterMacOS
import ServiceManagement
import UserNotifications

@main
class AppDelegate: FlutterAppDelegate {
  override func applicationShouldTerminateAfterLastWindowClosed(_ sender: NSApplication) -> Bool { false }

  override func applicationDidFinishLaunching(_ notification: Notification) {
    UNUserNotificationCenter.current().delegate = self
    let controller = mainFlutterWindow?.contentViewController as! FlutterViewController
    let ch = FlutterMethodChannel(name: "crier/macos", binaryMessenger: controller.engine.binaryMessenger)
    ch.setMethodCallHandler { call, result in
      switch call.method {
      case "loginItemEnable":
        do { try SMAppService.mainApp.register(); result(SMAppService.mainApp.status.rawValue) } catch { result(FlutterError(code: "sm", message: "\(error)", details: nil)) }
      case "loginItemDisable":
        do { try SMAppService.mainApp.unregister(); result(nil) } catch { result(FlutterError(code: "sm", message: "\(error)", details: nil)) }
      case "loginItemStatus": result(SMAppService.mainApp.status.rawValue) // 1 = enabled, 2 = requiresApproval
      case "openLoginItems": SMAppService.openSystemSettingsLoginItems(); result(nil)
      case "beginActivity":
        self.activity = ProcessInfo.processInfo.beginActivity(options: [.userInitiatedAllowingIdleSystemSleep], reason: "Publishing scheduled post")
        result(nil)
      case "endActivity":
        if let a = self.activity { ProcessInfo.processInfo.endActivity(a); self.activity = nil }
        result(nil)
      default: result(FlutterMethodNotImplemented)
      }
    }
  }
  private var activity: NSObjectProtocol?
}

import 'dart:io';
import 'package:launch_at_startup/launch_at_startup.dart';
import 'package:tray_manager/tray_manager.dart';
import 'package:window_manager/window_manager.dart';

Future<void> initDesktopResident() async {
  await windowManager.ensureInitialized();
  await windowManager.setPreventClose(true); // close button hides to tray instead
  launchAtStartup.setup(appName: 'Crier', appPath: Platform.resolvedExecutable /*, packageName: 'Crier' for MSIX */);
  // user opt-in: await launchAtStartup.enable();
  // tray icon + menu via tray_manager; onWindowClose -> windowManager.hide(); windowManager.setSkipTaskbar(true)
  Timer.periodic(const Duration(seconds: 30), (_) => scheduleEngine.publishDue());
}
